ALPHABET = ''.join(map(chr, range(32, 127)))

def encode(data: bytes, min_length=None):
    if not data:
        return ''
    n = int.from_bytes(data, 'big')
    if n == 0:
        return ALPHABET[0] * (min_length or 1)
    s = []
    while n:
        n, r = divmod(n, 95)
        s.append(ALPHABET[r])
    s = ''.join(reversed(s))
    return s.rjust(min_length, ALPHABET[0]) if min_length else s

import math
import base91
import misc.base95 as base95

BASE_ALPHABET = ''.join(chr(i) for i in range(32, 127))


class Base91:
    NAME = "Base91"
    ALPHABET_SIZE = 91

    @staticmethod
    def encode(data):
        return base91.encode(data)

    @staticmethod
    def decode(text):
        return base91.decode(text)

    @classmethod
    def bits_per_char(cls):
        return math.log2(cls.ALPHABET_SIZE)


class Base95:
    NAME = "Base95"
    ALPHABET_SIZE = len(base95.ALPHABET)

    @staticmethod
    def encode(data):
        return base95.encode(data)

    @staticmethod
    def decode(text):
        return base95.decode(text)

    @classmethod
    def bits_per_char(cls):
        return math.log2(cls.ALPHABET_SIZE)

#!/usr/bin/env perl
use strict;
use warnings;
use utf8;

$_ = '$Intent: $';

use POSIX qw(mkfifo);
use HTTP::Tiny;
use JSON::PP qw(encode_json decode_json);
use File::Spec;
use Crypt::PK::ECC;
use Crypt::Argon2 qw(argon2id_raw);
use Crypt::Digest::SHA256 qw(sha256_hex);
use Math::BigInt;

# =============================================================================
# CONFIGURATION
# =============================================================================
my $FIFO_PATH  = File::Spec->catfile('.', '.env');
my $SEEDER_URL = $ENV{SEEDER_URL} || 'http://127.0.0.1:5000/eval-oprf';
my $KEY_VER    = $ENV{KEY_VERSION} || "v1";
my $ARGON_SALT = pack("H*", $ENV{SALT_HEX} || "d9266e3cce2546b6a11f7e7d1fe6ae23");

# Domain Separation Tag for Hash-to-Curve
my $DST = "VOPRF-secp256r1-SHA256-v1";

# secp256r1 (NIST P-256) Subgroup Order n
my $SECP256R1_N = Math::BigInt->new("0xFFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551");

# =============================================================================
# SIGNAL & EXIT CLEANUP
# =============================================================================
my $cleanup_done = 0;
sub cleanup {
    return if $cleanup_done++;
    if (-e $FIFO_PATH) {
        unlink($FIFO_PATH) or warn "[-] Warning: Failed to unlink FIFO ($FIFO_PATH): $!\n";
    }
}

$SIG{INT}  = sub { cleanup(); exit 1; };
$SIG{TERM} = sub { cleanup(); exit 1; };
$SIG{PIPE} = sub { cleanup(); exit 1; };
END { cleanup(); }

# =============================================================================
# CRYPTOGRAPHIC HELPER FUNCTIONS
# =============================================================================
sub get_password_systemd {
    print "[+] Requesting master password via systemd-askpassword...\n";
    my $cmd = 'systemd-askpassword --icon=dialog-password "Enter Master Password:"';
    open(my $fh, '-|', $cmd) or die "[-] Failed to execute systemd-askpassword: $!\n";

    my $password = <$fh>;
    close($fh);

    die "[-] No password entered or prompt cancelled.\n" unless defined $password && length $password;
    chomp($password);
    return $password;
}

sub hash_to_curve_point {
    my ($plain_password) = @_;

    # 1. Compute SHA-256 digest over DST + Password
    my $hash_hex = sha256_hex($DST . $plain_password);

    # 2. Convert hash to BigInt and reduce modulo (n - 1) + 1 -> k in [1, n-1]
    my $hash_num = Math::BigInt->from_hex("0x" . $hash_hex);
    my $k_num    = ($hash_num->bmod($SECP256R1_N - 1))->badd(1);

    # 3. Format scalar k to a 32-byte (64 hex char) zero-padded hex string
    my $k_hex = $k_num->as_hex();
    $k_hex =~ s/^0x//i;
    $k_hex = sprintf("%064s", $k_hex);
    $k_hex =~ tr/ /0/;

    my $k_bytes = pack("H*", $k_hex);

    # 4. Point Multiplication: P = k * G
    my $pwd_ecc = Crypt::PK::ECC->new();
    $pwd_ecc->import_key_raw($k_bytes, "secp256r1");

    # Sanitize intermediate scalars
    $k_bytes = "\0" x length($k_bytes);
    return $pwd_ecc;
}

# =============================================================================
# MAIN EXECUTION PIPELINE
# =============================================================================

# 1. Prepare Clean FIFO
cleanup() if -e $FIFO_PATH;
mkfifo($FIFO_PATH, 0600) or die "[-] Failed to create FIFO ($FIFO_PATH): $!\n";
chmod 0600, $FIFO_PATH;
print "[+] FIFO initialized at $FIFO_PATH (mode 0600)\n";

# 2. Capture Password
my $plain_password = get_password_systemd();

# 3. Hash-to-Curve & Blinding
print "[+] Hashing password and blinding for V-OPRF query...\n";
my $pwd_ecc = hash_to_curve_point($plain_password);

my $blinding_key = Crypt::PK::ECC->new();
$blinding_key->generate_key("secp256r1"); 

my $blinded_raw = $blinding_key->shared_secret($pwd_ecc);
my $blinded_hex = unpack("H*", $blinded_raw);

# 4. Query Seeder
print "[+] Querying V-OPRF server at $SEEDER_URL...\n";
my $http = HTTP::Tiny->new(timeout => 10);
my $res  = $http->post($SEEDER_URL, {
    headers => { 'Content-Type' => 'application/json' },
    content => encode_json({ 
        blinded_element => $blinded_hex,
        key_version     => $KEY_VER
    }),
});

unless ($res->{success}) {
    $plain_password = "\0" x length($plain_password);
    die "[-] Seeder query failed (HTTP $res->{status}): $res->{content}\n";
}

my $res_data      = decode_json($res->{content});
my $evaluated_hex = $res_data->{evaluated_element} or die "[-] Missing evaluated_element\n";
my $mask_hex      = $res_data->{mask}              or die "[-] Missing rotation mask\n";

# 5. Unblind Response
my $oprf_pepper = pack("H*", $evaluated_hex);

# 6. Fortify with Argon2id
print "[+] Executing Argon2id key derivation...\n";
my $raw_ikm = argon2id_raw(
    $plain_password . $oprf_pepper,
    $ARGON_SALT,
    3,              # t_cost
    64 * 1024,      # m_cost (64 MB)
    4,              # parallelism
    32              # output length (32 bytes / 256 bits)
);

# 7. Apply XOR Mask
print "[+] Applying XOR mask (Key Version: $res_data->{key_version})...\n";
my $mask_bytes = pack("H*", $mask_hex);

die "[-] Mask length mismatch\n" unless length($mask_bytes) == length($raw_ikm);

# Bitwise XOR: S_effective = S_raw ^ M
my $effective_ikm = $raw_ikm ^ $mask_bytes;
my $axiom_ikm_hex = unpack("H*", $effective_ikm);

# 8. Stream to FIFO
print "[+] Streaming masked AXIOM_IKM to $FIFO_PATH (Waiting for auditor reader process)...\n";
open(my $fifo_fh, '>', $FIFO_PATH) or die "[-] Failed to open FIFO for writing: $!\n";
print $fifo_fh "AXIOM_IKM=$axiom_ikm_hex\n";
print $fifo_fh "AXIOM_KEY_VERSION=$res_data->{key_version}\n";
close($fifo_fh);

# 9. Sanitize Memory
$plain_password = "\0" x length($plain_password);
$oprf_pepper    = "\0" x length($oprf_pepper);
$raw_ikm        = "\0" x length($raw_ikm);
$mask_bytes     = "\0" x length($mask_bytes);
$effective_ikm  = "\0" x length($effective_ikm);
$axiom_ikm_hex  = "\0" x length($axiom_ikm_hex);

print "[+] Memory sanitized. FIFO read complete.\n";
exit 0;

1;
